#[kani::unwind(12)]
fn explicit_type_controls_company_identifier() {
    let kinds = [None, Some("company"), Some(" COMPANY "), Some("person"), Some("organisation"), Some("mystery"), Some("")];
    let choice: usize = kani::any();
    kani::assume(choice < kinds.len());
