#[kani::unwind(12)]
fn company_identifier_normalization() {
    let cases = [
        (None, None),
        (Some("00000001"), Some("00000001")),
        (Some(" ab123456 \t"), Some("AB123456")),
        (Some("ABCDEFGH"), None),
        (Some("1234567"), None),
        (Some("123456789"), None),
        (Some("00000!01"), None),
    ];
    let choice: usize = kani::any();
    kani::assume(choice < cases.len());
    let mut row = super::observation("a");
    row.donor_company_number = cases[choice].0.map(str::to_owned);
